#!/usr/bin/env bash
# ─────────────────────────────────────────────────────────────────────────────
# Pri Learning · clear merge conflicts on the generated iOS web bundles.
#
# Since decision D28 (1 November 2026) ios/*/Resources/Web is generated by
# `npm run build && npm run sync:ios` and ignored by git; only the placeholder
# README in each folder is tracked. A branch cut before that still tracks about
# 300 content-hashed files per mirror, so `git merge main` into it (or a rebase
# onto main) stops on a modify/delete conflict for every one of them.
#
# This script finishes exactly that part of the merge and nothing else:
#   1. removes every generated path under the two roots from the index (all
#      conflict stages) and from the working tree;
#   2. restores the tracked placeholder README from the side that has it;
#   3. stages the result and lists any conflicts that remain elsewhere.
# It never touches a path outside the two generated roots and never commits:
# finish with `git commit` (merge) or `git rebase --continue` yourself, then run
# `npm run build && npm run sync:ios` to regenerate the bundles locally.
# When the index already holds only the placeholders there is nothing to
# resolve: it says so and exits 0 without touching the working tree, so a
# locally generated (ignored) bundle survives an accidental run.
#
#   scripts/resolve-generated-conflicts.sh            # after the merge/rebase stopped
#   scripts/resolve-generated-conflicts.sh --dry-run  # print what would change
# ─────────────────────────────────────────────────────────────────────────────
set -euo pipefail

ROOTS=('ios/PriLearning.swiftpm/Resources/Web' 'ios/PriLearning 2.swiftpm/Resources/Web')
PLACEHOLDER='README.md'
DRY_RUN=0

usage() { sed -n '3,24p' "$0" | sed 's/^# \{0,1\}//'; }

for arg in "$@"; do
  case "$arg" in
    --dry-run) DRY_RUN=1 ;;
    -h|--help) usage; exit 0 ;;
    *) echo "unknown argument: $arg" >&2; usage >&2; exit 2 ;;
  esac
done

top="$(git rev-parse --show-toplevel)"
cd "$top"
git_dir="$(git rev-parse --git-dir)"

# Where to take the placeholder from: the incoming side of a merge, the base of
# a rebase, then whatever main is called here.
sources=()
[[ -f "$git_dir/MERGE_HEAD" ]] && sources+=(MERGE_HEAD)
sources+=(HEAD)
for ref in origin/main main; do
  git rev-parse -q --verify "$ref^{commit}" >/dev/null 2>&1 && sources+=("$ref")
done

# Every index entry (any stage) under the roots that is not a placeholder.
generated="$(git ls-files -z --cached -- "${ROOTS[@]}" | tr '\0' '\n' | awk -v p="$PLACEHOLDER" '
  { n = split($0, parts, "/"); if (parts[n] != p) print }' | sort -u)"
count=0
[[ -n "$generated" ]] && count="$(printf '%s\n' "$generated" | wc -l | tr -d ' ')"
unmerged_before="$(git diff --name-only --diff-filter=U | wc -l | tr -d ' ')"
in_progress='no'
for marker in MERGE_HEAD rebase-merge rebase-apply; do
  [[ -e "$git_dir/$marker" ]] && in_progress='yes'
done

echo "generated bundle entries in the index: $count (unmerged paths before: $unmerged_before; merge or rebase in progress: $in_progress)"

# Nothing to resolve: the index already holds only the placeholders. On a
# branch that is not mid-merge this is the normal post-D28 state, and a
# locally generated bundle (ignored by git) must be left exactly as it is.
if [[ "$count" -eq 0 ]]; then
  echo "nothing to do: the index holds no generated bundle entry under either root; the working tree was not touched."
  if [[ "$in_progress" == 'yes' && "$unmerged_before" -gt 0 ]]; then
    echo "the $unmerged_before unmerged path(s) are outside the generated roots; resolve them, then finish the merge or rebase."
  fi
  exit 0
fi

if [[ "$DRY_RUN" -eq 1 ]]; then
  if [[ -n "$generated" ]]; then
    printf '%s\n' "$generated" | head -12 | while IFS= read -r file; do echo "  would remove from index: $file"; done
  fi
  [[ "$count" -gt 12 ]] && echo "  ... and $((count - 12)) more"
  for root in "${ROOTS[@]}"; do
    echo "  would clear working tree under $root (keeping $PLACEHOLDER)"
  done
  echo "  would restore $PLACEHOLDER from the first of: ${sources[*]}"
  exit 0
fi

# 1. Index: drop every stage of every generated path. `git rm --cached` resolves
#    an unmerged path by deletion, which is the correct resolution here.
if [[ -n "$generated" ]]; then
  printf '%s\n' "$generated" | tr '\n' '\0' | \
    git rm -q --cached --ignore-unmatch --pathspec-from-file=- --pathspec-file-nul
fi

# 2. Working tree: everything under the roots except the placeholder.
for root in "${ROOTS[@]}"; do
  if [[ -d "$root" ]]; then
    find "$root" -mindepth 1 -maxdepth 1 ! -name "$PLACEHOLDER" -exec rm -rf {} +
  fi
done

# 3. Placeholder: from the side that already untracked the bundles.
for root in "${ROOTS[@]}"; do
  restored=''
  for src in "${sources[@]}"; do
    if git cat-file -e "$src:$root/$PLACEHOLDER" 2>/dev/null; then
      mkdir -p "$root"
      git show "$src:$root/$PLACEHOLDER" > "$root/$PLACEHOLDER"
      git add -- "$root/$PLACEHOLDER"
      restored="$src"
      break
    fi
  done
  if [[ -n "$restored" ]]; then
    echo "restored $root/$PLACEHOLDER from $restored"
  else
    echo "note: no side carries $root/$PLACEHOLDER; merge or rebase onto a main that has it (Package.swift needs the folder)." >&2
  fi
done

remaining="$(git diff --name-only --diff-filter=U || true)"
if [[ -n "$remaining" ]]; then
  echo "generated bundle conflicts cleared; conflicts remaining outside the generated roots:"
  printf '%s\n' "$remaining" | while IFS= read -r file; do echo "  $file"; done
  echo "resolve those, then finish the merge or rebase."
else
  echo "generated bundle conflicts cleared; no unmerged paths remain. Finish with git commit (merge) or git rebase --continue."
fi
echo "then regenerate locally: npm run build && npm run sync:ios && npm run check:ios"
